from pathlib import Path
import base64,zlib,hashlib
root=Path("/root/nlos_stage2/hybrid_fista_20261031")
files={'arm/hybrid_solver.py': '', 'arm/libhybrid_mmio.so': '', 'arm/hybrid_mmio.c': ''}
for name,value in files.items():
 p=root/name;data=zlib.decompress(base64.b64decode(value))
 if p.exists() and p.read_bytes()!=data and not p.with_suffix(p.suffix+'.before_native').exists():p.with_suffix(p.suffix+'.before_native').write_bytes(p.read_bytes())
 p.write_bytes(data)
 print('NATIVE_PATCH',name,hashlib.sha256(data).hexdigest())
print('NATIVE_MMIO_PATCH_INSTALLED')
